<script setup lang="ts">
import {onMounted,onUnmounted,ref} from "vue";
import * as api from "../api"; import type {ScratchItem} from "../types"; import {showToast} from "../store";import ConfirmDialog from"./ConfirmDialog.vue";
const items=ref<ScratchItem[]>([]),draft=ref(""),saving=ref(false); const timers=new Map<number,number>();
async function load(){items.value=await api.listScratchItems()}
async function add(){if(!draft.value.trim()||saving.value)return;saving.value=true;try{await api.createScratchItem(draft.value);draft.value="";await load()}finally{saving.value=false}}
function autosave(item:ScratchItem){window.clearTimeout(timers.get(item.id));timers.set(item.id,window.setTimeout(async()=>{if(item.content.trim())await api.updateScratchItem(item.id,item.content)},500))}
const confirm=ref<{kind:"delete"|"clear";id?:number}|null>(null);async function remove(id:number){confirm.value={kind:"delete",id}}
async function copy(text:string){await api.copyText(text);showToast("已复制")}
async function clear(){if(items.value.length)confirm.value={kind:"clear"}}async function confirmed(){if(confirm.value?.kind==="clear")await api.clearScratchItems();else if(confirm.value?.id)await api.deleteScratchItem(confirm.value.id);confirm.value=null;await load()}
onMounted(()=>void load());onUnmounted(()=>timers.forEach(window.clearTimeout));
</script>
<template><section class="scratch"><header><div><h1>临时区</h1><p>快速保存文本、命令、链接或短笔记</p></div><button class="danger" :disabled="!items.length" @click="clear">清空</button></header><div class="composer"><textarea v-model="draft" autofocus placeholder="直接粘贴或输入多行内容…"></textarea><button :disabled="saving||!draft.trim()" @click="add">保存到临时区</button></div><div class="scratch-list"><article v-for="item in items" :key="item.id"><textarea v-model="item.content" @input="autosave(item)"></textarea><footer><time>{{new Date(item.updatedAt).toLocaleString()}}</time><button @click="copy(item.content)">复制</button><button class="danger" @click="remove(item.id)">删除</button></footer></article><p v-if="!items.length" class="empty">还没有临时内容。在上方粘贴即可保存。</p></div></section><ConfirmDialog v-if="confirm" title="确认删除" danger confirm-text="删除" :message="confirm.kind==='clear'?'确认清空全部临时内容？此操作无法撤销。':'删除这条临时内容？'" @confirm="confirmed" @cancel="confirm=null"/></template>
<style scoped>.scratch{height:100%;min-height:0;display:flex;flex-direction:column;padding:18px;gap:14px;overflow:hidden}header{display:flex;justify-content:space-between;align-items:center}h1{margin:0;color:var(--text-bright);font-size:var(--font-lg)}p{margin:4px 0;color:var(--text-dim)}button{padding:7px 12px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);color:var(--text);cursor:pointer}button:hover{background:var(--hover)}button:disabled{opacity:.45;cursor:not-allowed}.danger{color:var(--danger)}.composer{display:flex;gap:8px;align-items:stretch}.composer textarea{min-height:82px}.composer button{background:var(--accent);color:white}textarea{width:100%;resize:vertical;padding:10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);color:var(--text);font:inherit;line-height:var(--line);outline:none}.scratch-list{min-height:0;overflow:auto;display:flex;flex-direction:column;gap:10px}article{padding:10px;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius)}article textarea{min-height:80px;font-family:var(--mono)}footer{display:flex;align-items:center;gap:7px;margin-top:7px}time{margin-right:auto;color:var(--text-faint);font-size:var(--font-sm)}.empty{text-align:center;padding:28px}</style>
